from solution import factorial

def test_factorial_zero():
    assert factorial(0) == 1

def test_factorial_five():
    assert factorial(5) == 120

def test_factorial_one():
    assert factorial(1) == 1

from solution import is_palindrome

def test_palindrome_simple():
    assert is_palindrome('racecar') is True

def test_not_palindrome():
    assert is_palindrome('hello') is False

def test_palindrome_case_insensitive():
    assert is_palindrome('Racecar') is True

from solution import sum_list

def test_sum_empty():
    assert sum_list([]) == 0

def test_sum_positive():
    assert sum_list([1, 2, 3, 4]) == 10

def test_sum_negative():
    assert sum_list([-1, 1, 5]) == 5

from solution import reverse_string

def test_reverse_hello():
    assert reverse_string('hello') == 'olleh'

def test_reverse_empty():
    assert reverse_string('') == ''

def test_reverse_single():
    assert reverse_string('a') == 'a'

from solution import fibonacci

def test_fib_zero():
    assert fibonacci(0) == 0

def test_fib_one():
    assert fibonacci(1) == 1

def test_fib_ten():
    assert fibonacci(10) == 55

import pytest
from solution import max_in_list

def test_max_positive():
    assert max_in_list([3, 1, 4, 1, 5]) == 5

def test_max_negative():
    assert max_in_list([-3, -1, -4]) == -1

def test_max_empty_raises():
    with pytest.raises(ValueError):
        max_in_list([])

from solution import count_vowels

